import sys,json,_codecs,warnings,unicodedata
rows=json.load(sys.stdin)
out=[]
for r in rows:
 with warnings.catch_warnings(record=True) as ws:
  warnings.simplefilter('always')
  try:
   s,n=getattr(_codecs,'raw_unicode_escape_decode' if r['raw'] else 'unicode_escape_decode')(bytes(r['bytes']),r['errors'],r['final'])
   result={'result':[list(map(ord,s)),n]}
  except UnicodeDecodeError as e: result={'error':[e.encoding,list(e.object),e.start,e.end,e.reason]}
  result['warnings']=[str(w.message) for w in ws]
  out.append(result)
json.dump({'reference':{'version':sys.version,'unicode':unicodedata.unidata_version,'platform':sys.platform,'byteorder':sys.byteorder},'results':out},sys.stdout)
